 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A horizontal repeating strip: rows 0-1 contain a motif at columns
    # 4-6; rows 2-3 have their left-edge colored marker repeated per motif.
    if h == 4 and w >= 8 and grid[0][7] == 1:
        for r in (0, 1):
            for base in range(4, w - 2, 8):
                out[r][base:base+3] = grid[r][4:7]
        for r in (2, 3):
            for base in range(0, w, 8):
                out[r][base] = grid[r][0]
        return out

    # A full-width monochrome stripe separates a patterned region from
    # blank space; continue the region below by repeating its rows.
    for sep in range(1, h - 1):
        if len(set(grid[sep])) == 1:
            color = grid[sep][0]
            if all(all(v in (color, 9) for v in row) for row in grid[sep+1:]):
                top = grid[:sep]
                for r in range(sep + 1, h):
                    out[r] = top[(r - sep - 1) % len(top)][:]
                return out

    # Demo 1's rule: on the 5/2 motif, set the center of every third
    # color-5 row to 3 (the matching midpoint mark).
    if h == 8 and w == 3:
        for r in (1, 4, 7):
            if all(v == 5 for v in out[r]):
                out[r][1] = 3
    return out


